 * System-Assigned Managed Identity Example
 * 
 * This example demonstrates using a system-assigned managed identity
 * to authenticate Azure SDK clients.
 */

import { ManagedIdentityCredential } from '@azure/identity';
import { BlobServiceClient } from '@azure/storage-blob';
import { SecretClient } from '@azure/keyvault-secrets';
import { CosmosClient } from '@azure/cosmos';

/**
 * Example 1: Using system-assigned identity with Azure Blob Storage
 */
export async function useBlobStorageWithSystemIdentity(): Promise<void> {
  try {
    // Create credential - no parameters needed for system-assigned identity
    const credential = new ManagedIdentityCredential();

    // Create Azure Storage client
    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    // Use the client
    const containerClient = blobServiceClient.getContainerClient('mycontainer');

    console.log('Listing blobs...');
    for await (const blob of containerClient.listBlobsFlat()) {
      console.log(`- ${blob.name}`);
    }

    console.log('✓ Successfully authenticated with system-assigned identity');
  } catch (error) {
    handleAuthenticationError(error, 'system-assigned');
  }
}

/**
 * Example 2: Using system-assigned identity with Azure Key Vault
 */
export async function useKeyVaultWithSystemIdentity(): Promise<void> {
  try {
    const credential = new ManagedIdentityCredential();

    // Create Key Vault client
    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const client = new SecretClient(vaultUrl, credential);

    // Retrieve a secret
    const secretName = 'my-secret';
    const secret = await client.getSecret(secretName);

    console.log(`✓ Retrieved secret: ${secretName}`);
    console.log(`  Secret value length: ${secret.value?.length || 0} characters`);
  } catch (error) {
    handleAuthenticationError(error, 'system-assigned');
  }
}

/**
 * Example 3: Using system-assigned identity with Azure Cosmos DB
 */
export async function useCosmosDbWithSystemIdentity(): Promise<void> {
  try {
    const credential = new ManagedIdentityCredential();

    // Create Cosmos DB client
    const endpoint = process.env.COSMOS_ENDPOINT || 'https://mycosmosdb.documents.azure.com:443/';
    const client = new CosmosClient({
      endpoint,
      aadCredentials: credential
    });

    // Use the client
    const { databases } = await client.databases.readAll().fetchAll();
    console.log(`✓ Connected to Cosmos DB. Found ${databases.length} databases`);
  } catch (error) {
    handleAuthenticationError(error, 'system-assigned');
  }
}

/**
 * Example 4: Multiple Azure services with single credential instance
 * Best practice: Reuse credential instances
 */
export async function useMultipleServicesWithSystemIdentity(): Promise<void> {
  // Create credential once
  const credential = new ManagedIdentityCredential();

  try {
    // Use with multiple services
    const storageAccountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${storageAccountName}.blob.core.windows.net`,
      credential
    );

    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const secretClient = new SecretClient(vaultUrl, credential);

    // Perform operations
    await Promise.all([
      blobServiceClient.getContainerClient('test').exists(),
      secretClient.getSecret('test-secret').catch(() => null)
    ]);

    console.log('✓ Successfully used system-assigned identity with multiple services');
  } catch (error) {
    handleAuthenticationError(error, 'system-assigned');
  }
}

/**
 * Example 5: With explicit logging for troubleshooting
 */
export async function useWithLogging(): Promise<void> {
  try {
    const credential = new ManagedIdentityCredential({
      // Enable logging for troubleshooting
      loggingOptions: {
        enableUncheckedCertificateChain: false,
        allowLoggingAccountIdentifiers: true
      }
    });

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    const exists = await containerClient.exists();

    console.log(`✓ Container exists: ${exists}`);
  } catch (error) {
    handleAuthenticationError(error, 'system-assigned');
  }
}

/**
 * Centralized error handling for authentication issues
 */
function handleAuthenticationError(error: any, identityType: string): void {
  console.error(`\n❌ Authentication failed with ${identityType} identity\n`);

  if (error.code === 'ENOTFOUND' || error.message?.includes('ENOTFOUND')) {
    console.error('Network Error: Cannot reach the service endpoint');
    console.error('Check: Network connectivity and firewall rules');
  } else if (error.statusCode === 403 || error.message?.includes('Forbidden')) {
    console.error('Authorization Error: Identity lacks required permissions');
    console.error('Check: RBAC role assignments for the managed identity');
  } else if (error.message?.includes('ManagedIdentityCredential')) {
    console.error('Identity Error: Managed identity not available or misconfigured');
    console.error('Check:');
    console.error('  1. Managed identity is enabled on the resource');
    console.error('  2. Running on Azure (App Service, VM, Container Instance, etc.)');
    console.error('  3. IDENTITY_ENDPOINT environment variable is set');
  } else if (error.code === 'CredentialUnavailableError') {
    console.error('Credential Unavailable: Not running in a managed identity environment');
    console.error('Solution: Use DefaultAzureCredential for local development fallback');
  } else {
    console.error('Unexpected Error:', error.message);
    console.error('Full error:', error);
  }

  throw error;
}

// Example usage
if (require.main === module) {
  (async () => {
    console.log('=== System-Assigned Managed Identity Examples ===\n');

    try {
      await useBlobStorageWithSystemIdentity();
    } catch (error) {
      // Error already logged
    }
  })();
}
