{"file_text":"/**
 * User-Assigned Managed Identity Example
 * 
 * This example demonstrates using a user-assigned managed identity
 * to authenticate Azure SDK clients.
 */

import { ManagedIdentityCredential } from '@azure/identity';
import { BlobServiceClient } from '@azure/storage-blob';
import { SecretClient } from '@azure/keyvault-secrets';
import { QueueServiceClient } from '@azure/storage-queue';

/**
 * Example 1: Using user-assigned identity with Client ID (recommended)
 */
export async function useBlobStorageWithUserIdentity(): Promise<void> {
  try {
    // Get client ID from environment variable (best practice)
    const clientId = process.env.USER_ASSIGNED_IDENTITY_CLIENT_ID;

    if (!clientId) {
      throw new Error('USER_ASSIGNED_IDENTITY_CLIENT_ID environment variable is required');
    }

    // Create credential with client ID
    const credential = new ManagedIdentityCredential({ clientId });

    // Create Azure Storage client
    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    // Use the client
    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    const properties = await containerClient.getProperties();

    console.log(`✓ Successfully authenticated with user-assigned identity (Client ID)`);
    console.log(`  Container: ${containerClient.containerName}`);
    console.log(`  Last modified: ${properties.lastModified}`);
  } catch (error) {
    handleAuthenticationError(error, 'user-assigned');
  }
}

/**
 * Example 2: Using user-assigned identity with Resource ID
 */
export async function useKeyVaultWithResourceId(): Promise<void> {
  try {
    // Full ARM resource ID of the user-assigned identity
    const resourceId = process.env.USER_ASSIGNED_IDENTITY_RESOURCE_ID;

    if (!resourceId) {
      throw new Error('USER_ASSIGNED_IDENTITY_RESOURCE_ID environment variable is required');
    }

    // Create credential with resource ID
    const credential = new ManagedIdentityCredential({ resourceId });

    // Create Key Vault client
    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const client = new SecretClient(vaultUrl, credential);

    // List secrets
    console.log('Listing secrets in Key Vault...');
    const secretsIterator = client.listPropertiesOfSecrets();

    let count = 0;
    for await (const secretProperties of secretsIterator) {
      console.log(`  - ${secretProperties.name}`);
      count++;
    }

    console.log(`✓ Successfully listed ${count} secrets with user-assigned identity (Resource ID)`);
  } catch (error) {
    handleAuthenticationError(error, 'user-assigned');
  }
}

/**
 * Example 3: Multiple user-assigned identities on same resource
 * When a resource has multiple user-assigned identities, you must specify which one to use
 */
export async function useMultipleUserAssignedIdentities(): Promise<void> {
  // Scenario: Resource has two user-assigned identities
  // - One for storage access
  // - One for Key Vault access

  const storageIdentityClientId = process.env.STORAGE_IDENTITY_CLIENT_ID;
  const keyVaultIdentityClientId = process.env.KEYVAULT_IDENTITY_CLIENT_ID;

  if (!storageIdentityClientId || !keyVaultIdentityClientId) {
    throw new Error('Both STORAGE_IDENTITY_CLIENT_ID and KEYVAULT_IDENTITY_CLIENT_ID are required');
  }

  try {
    // Create separate credentials for each identity
    const storageCredential = new ManagedIdentityCredential({ 
      clientId: storageIdentityClientId 
    });

    const keyVaultCredential = new ManagedIdentityCredential({ 
      clientId: keyVaultIdentityClientId 
    });

    // Use appropriate identity for each service
    const storageAccountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${storageAccountName}.blob.core.windows.net`,
      storageCredential
    );

    const queueServiceClient = new QueueServiceClient(
      `https://${storageAccountName}.queue.core.windows.net`,
      storageCredential
    );

    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const secretClient = new SecretClient(vaultUrl, keyVaultCredential);

    // Perform operations with appropriate identities
    await Promise.all([
      blobServiceClient.getContainerClient('test').exists(),
      queueServiceClient.getQueueClient('test').exists(),
      secretClient.getSecret('test-secret').catch(() => null)
    ]);

    console.log('✓ Successfully used multiple user-assigned identities');
  } catch (error) {
    handleAuthenticationError(error, 'user-assigned');
  }
}

/**
 * Example 4: Dynamic identity selection based on environment
 */
export async function useDynamicIdentitySelection(): Promise<void> {
  const environment = process.env.ENVIRONMENT || 'dev';

  // Different identities for different environments
  const identityConfig = {
    dev: process.env.DEV_IDENTITY_CLIENT_ID,
    staging: process.env.STAGING_IDENTITY_CLIENT_ID,
    prod: process.env.PROD_IDENTITY_CLIENT_ID
  };

  const clientId = identityConfig[environment as keyof typeof identityConfig];

  if (!clientId) {
    throw new Error(`No identity configured for environment: ${environment}`);
  }

  try {
    const credential = new ManagedIdentityCredential({ clientId });

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    await containerClient.exists();

    console.log(`✓ Successfully authenticated with ${environment} identity`);
    console.log(`  Client ID: ${clientId.substring(0, 8)}...`);
  } catch (error) {
    handleAuthenticationError(error, 'user-assigned');
  }
}

/**
 * Example 5: With retry logic for transient failures
 */
export async function useWithRetryLogic(): Promise<void> {
  const clientId = process.env.USER_ASSIGNED_IDENTITY_CLIENT_ID;

  if (!clientId) {
    throw new Error('USER_ASSIGNED_IDENTITY_CLIENT_ID environment variable is required');
  }

  const credential = new ManagedIdentityCredential({ clientId });

  // Retry configuration
  const maxRetries = 3;
  const retryDelayMs = 1000;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
      const blobServiceClient = new BlobServiceClient(
        `https://${accountName}.blob.core.windows.net`,
        credential
      );

      const containerClient = blobServiceClient.getContainerClient('mycontainer');
      await containerClient.exists();

      console.log(`✓ Successfully authenticated on attempt ${attempt}`);
      return;
    } catch (error: any) {
      console.log(`  Attempt ${attempt}/${maxRetries} failed`);

      // Don't retry on authorization errors (403) - these won't fix themselves
      if (error.statusCode === 403) {
        console.error('❌ Authorization error - retrying won\'t help');
        throw error;
      }

      // Don't retry on invalid identity errors
      if (error.message?.includes('invalid')) {
        console.error('❌ Invalid identity - retrying won\'t help');
        throw error;
      }

      if (attempt === maxRetries) {
        console.error(`❌ All ${maxRetries} attempts failed`);
        throw error;
      }

      // Wait before retrying
      console.log(`  Waiting ${retryDelayMs}ms before retry...`);
      await new Promise(resolve => setTimeout(resolve, retryDelayMs * attempt));
    }
  }
}

/**
 * Example 6: Validating user-assigned identity configuration
 */
export async function validateUserAssignedIdentityConfig(): Promise<boolean> {
  console.log('Validating user-assigned identity configuration...\n');

  const clientId = process.env.USER_ASSIGNED_IDENTITY_CLIENT_ID;
  const resourceId = process.env.USER_ASSIGNED_IDENTITY_RESOURCE_ID;

  // Check if identity is configured
  if (!clientId && !resourceId) {
    console.error('❌ No user-assigned identity configured');
    console.error('   Set either USER_ASSIGNED_IDENTITY_CLIENT_ID or USER_ASSIGNED_IDENTITY_RESOURCE_ID');
    return false;
  }

  console.log('✓ Identity configuration found:');
  if (clientId) {
    console.log(`  Client ID: ${clientId.substring(0, 8)}...${clientId.substring(clientId.length - 4)}`);
  }
  if (resourceId) {
    console.log(`  Resource ID: ${resourceId}`);
  }

  // Try to get a token to validate the identity
  try {
    const credential = new ManagedIdentityCredential(
      clientId ? { clientId } : { resourceId: resourceId! }
    );

    // Request a token for Azure Storage scope
    const token = await credential.getToken('https://storage.azure.com/.default');

    console.log('\n✓ Successfully obtained token');
    console.log(`  Token expires at: ${new Date(token.expiresOnTimestamp).toISOString()}`);
    console.log(`  Token valid for: ${Math.round((token.expiresOnTimestamp - Date.now()) / 1000 / 60)} minutes`);

    return true;
  } catch (error: any) {
    console.error('\n❌ Failed to obtain token');
    console.error(`   Error: ${error.message}`);
    return false;
  }
}

/**
 * Centralized error handling for authentication issues
 */
function handleAuthenticationError(error: any, identityType: string): void {
  console.error(`\n❌ Authentication failed with ${identityType} identity\n`);

  if (error.message?.includes('client_id')) {
    console.error('Client ID Error: Invalid or missing client ID');
    console.error('Check:');
    console.error('  1. USER_ASSIGNED_IDENTITY_CLIENT_ID is set correctly');
    console.error('  2. Client ID matches your user-assigned identity');
    console.error('  3. Identity is assigned to this resource');
  } else if (error.message?.includes('resource_id')) {
    console.error('Resource ID Error: Invalid or missing resource ID');
    console.error('Check: USER_ASSIGNED_IDENTITY_RESOURCE_ID format');
    console.error('Format: /subscriptions/{sub}/resourcegroups/{rg}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{name}');
  } else if (error.statusCode === 403 || error.message?.includes('Forbidden')) {
    console.error('Authorization Error: Identity lacks required permissions');
    console.error('Check:');
    console.error('  1. User-assigned identity has appropriate RBAC roles');
    console.error('  2. Role assignments are applied to correct resources');
    console.error('  3. Propagation delay (can take 5-10 minutes)');
  } else if (error.message?.includes('ManagedIdentityCredential')) {
    console.error('Identity Error: User-assigned identity not available');
    console.error('Check:');
    console.error('  1. User-assigned identity exists in Azure');
    console.error('  2. Identity is assigned to this resource');
    console.error('  3. Running on Azure (App Service, VM, Container Instance, etc.)');
  } else {
    console.error('Unexpected Error:', error.message);
    console.error('Full error:', error);
  }

  throw error;
}

// Example usage
if (require.main === module) {
  (async () => {
    console.log('=== User-Assigned Managed Identity Examples ===\n');

    // Validate configuration first
    const isValid = await validateUserAssignedIdentityConfig();

    if (isValid) {
      console.log('\n---\n');
      await useBlobStorageWithUserIdentity();
    }
  })();
}
