{"file_text":"/**
 * Local Development Fallback Strategies
 * 
 * This file demonstrates different strategies for handling authentication
 * in both Azure (with managed identity) and local development environments.
 */

import {
  ManagedIdentityCredential,
  DefaultAzureCredential,
  ChainedTokenCredential,
  AzureCliCredential,
  EnvironmentCredential,
  TokenCredential
} from '@azure/identity';
import { BlobServiceClient } from '@azure/storage-blob';
import { SecretClient } from '@azure/keyvault-secrets';

/**
 * Strategy 1: DefaultAzureCredential (RECOMMENDED)
 * 
 * Tries multiple authentication methods in order:
 * 1. EnvironmentCredential (env vars: AZURE_CLIENT_ID, AZURE_TENANT_ID, AZURE_CLIENT_SECRET)
 * 2. WorkloadIdentityCredential (Kubernetes)
 * 3. ManagedIdentityCredential (Azure resources)
 * 4. AzureCliCredential (az login)
 * 5. AzurePowerShellCredential (Connect-AzAccount)
 * 
 * This is the recommended approach for most scenarios.
 */
export async function useDefaultAzureCredential(): Promise<void> {
  console.log('Strategy 1: DefaultAzureCredential\n');

  try {
    // Simple - works in Azure AND local development
    const credential = new DefaultAzureCredential();

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    const exists = await containerClient.exists();

    console.log('✓ Authentication successful with DefaultAzureCredential');
    console.log(`  Container exists: ${exists}`);
    console.log('  This works in both Azure and local development!');
  } catch (error: any) {
    console.error('❌ Authentication failed');
    console.error(`  Error: ${error.message}`);
    console.error('\nLocal development setup:');
    console.error('  Run: az login');
    console.error('  Or set environment variables: AZURE_CLIENT_ID, AZURE_TENANT_ID, AZURE_CLIENT_SECRET');
  }
}

/**
 * Strategy 2: ChainedTokenCredential with Custom Order
 * 
 * Gives you explicit control over the authentication fallback chain.
 * Useful when you want specific behavior or need to debug authentication flow.
 */
export async function useChainedTokenCredential(): Promise<void> {
  console.log('Strategy 2: ChainedTokenCredential\n');

  try {
    // User-assigned identity in Azure
    const userAssignedClientId = process.env.USER_ASSIGNED_IDENTITY_CLIENT_ID;

    // Create credential chain with explicit order
    const credential = new ChainedTokenCredential(
      // 1. Try environment variables first (for CI/CD pipelines)
      new EnvironmentCredential(),

      // 2. Try user-assigned managed identity if client ID is provided
      ...(userAssignedClientId 
        ? [new ManagedIdentityCredential({ clientId: userAssignedClientId })]
        : []),

      // 3. Try system-assigned managed identity
      new ManagedIdentityCredential(),

      // 4. Fall back to Azure CLI (for local development)
      new AzureCliCredential()
    );

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    await containerClient.exists();

    console.log('✓ Authentication successful with ChainedTokenCredential');
    console.log('  Credential chain tried in order:');
    console.log('    1. Environment variables');
    if (userAssignedClientId) {
      console.log('    2. User-assigned managed identity');
      console.log('    3. System-assigned managed identity');
      console.log('    4. Azure CLI');
    } else {
      console.log('    2. System-assigned managed identity');
      console.log('    3. Azure CLI');
    }
  } catch (error: any) {
    console.error('❌ All credential sources failed');
    console.error(`  Error: ${error.message}`);
  }
}

/**
 * Strategy 3: Environment-Based Selection
 * 
 * Explicitly choose credential type based on environment.
 * Good for scenarios where you want different behavior per environment.
 */
export function createCredentialForEnvironment(): TokenCredential {
  const environment = process.env.NODE_ENV || 'development';
  const isAzure = process.env.WEBSITE_INSTANCE_ID || process.env.IDENTITY_ENDPOINT;

  console.log(`Creating credential for environment: ${environment}`);
  console.log(`Running in Azure: ${!!isAzure}\n`);

  if (isAzure) {
    // Running in Azure - use managed identity
    const clientId = process.env.USER_ASSIGNED_IDENTITY_CLIENT_ID;

    if (clientId) {
      console.log('→ Using user-assigned managed identity');
      return new ManagedIdentityCredential({ clientId });
    } else {
      console.log('→ Using system-assigned managed identity');
      return new ManagedIdentityCredential();
    }
  } else {
    // Local development
    if (environment === 'development') {
      console.log('→ Using Azure CLI credential (local development)');
      return new AzureCliCredential();
    } else {
      // CI/CD or other non-Azure environments
      console.log('→ Using environment credential (CI/CD)');
      return new EnvironmentCredential();
    }
  }
}

export async function useEnvironmentBasedCredential(): Promise<void> {
  console.log('Strategy 3: Environment-Based Selection\n');

  try {
    const credential = createCredentialForEnvironment();

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    await containerClient.exists();

    console.log('\n✓ Authentication successful');
  } catch (error: any) {
    console.error('\n❌ Authentication failed');
    console.error(`  Error: ${error.message}`);
  }
}

/**
 * Strategy 4: Graceful Degradation with Feature Flags
 * 
 * Use managed identity in Azure, but allow disabling for testing.
 */
export async function useWithFeatureFlags(): Promise<void> {
  console.log('Strategy 4: Graceful Degradation with Feature Flags\n');

  const useManagedIdentity = process.env.USE_MANAGED_IDENTITY !== 'false';
  const useAzureCli = process.env.USE_AZURE_CLI === 'true';

  try {
    let credential: TokenCredential;

    if (useManagedIdentity) {
      console.log('→ Managed Identity: ENABLED');
      credential = new DefaultAzureCredential();
    } else if (useAzureCli) {
      console.log('→ Azure CLI: ENABLED');
      credential = new AzureCliCredential();
    } else {
      console.log('→ Environment Variables: ENABLED');
      credential = new EnvironmentCredential();
    }

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    const containerClient = blobServiceClient.getContainerClient('mycontainer');
    await containerClient.exists();

    console.log('\n✓ Authentication successful');
  } catch (error: any) {
    console.error('\n❌ Authentication failed');
    console.error(`  Error: ${error.message}`);
  }
}

/**
 * Strategy 5: With Comprehensive Error Handling and Logging
 */
export async function useWithDetailedLogging(): Promise<void> {
  console.log('Strategy 5: Comprehensive Error Handling\n');

  try {
    // Enable logging for troubleshooting
    const credential = new DefaultAzureCredential({
      loggingOptions: {
        allowLoggingAccountIdentifiers: true
      }
    });

    console.log('Attempting authentication...');

    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const client = new SecretClient(vaultUrl, credential);

    // Try to get a secret
    const secretName = 'test-secret';
    console.log(`  Retrieving secret: ${secretName}`);

    try {
      const secret = await client.getSecret(secretName);
      console.log('✓ Successfully retrieved secret');
      console.log(`  Secret version: ${secret.properties.version}`);
    } catch (secretError: any) {
      if (secretError.statusCode === 404) {
        console.log(`  Secret '${secretName}' not found (404)`);
        console.log('✓ Authentication worked, but secret doesn\'t exist');
      } else {
        throw secretError;
      }
    }
  } catch (error: any) {
    console.error('❌ Authentication or authorization failed\n');

    // Detailed error diagnosis
    if (error.code === 'CredentialUnavailableError') {
      console.error('Problem: No credentials available');
      console.error('\nSolutions:');
      console.error('  Azure:');
      console.error('    - Enable managed identity on your resource');
      console.error('    - Verify IDENTITY_ENDPOINT environment variable');
