  if (error.statusCode === 403 || error.code === 'Forbidden') {
    console.error('Issue: Authorization denied');
    console.error('Possible causes:');
    console.error('  - Missing RBAC role assignment');
    console.error('  - Wrong scope for role assignment');
    console.error('  - Role assignment not yet propagated (5-10 min delay)\n');
    console.error('Solutions:');
    console.error('  1. Check role assignments:');
