    console.error('  2. Grant required role:');
    console.error(`     az role assignment create --role "<RoleName>" --assignee <identity-principal-id>`);
    console.error('  3. Wait 5-10 minutes for propagation');
    return;
  }

  // 3. Authentication errors
  if (error.message?.includes('authentication') || error.message?.includes('ManagedIdentityCredential')) {
