  if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
    console.error('Issue: Network connectivity problem');
    console.error('Possible causes:');
    console.error('  - Service endpoint unreachable');
    console.error('  - Firewall blocking outbound traffic');
    console.error('  - Incorrect service URL\n');
    console.error('Solutions:');
    console.error('  1. Check network connectivity');
    console.error('  2. Verify service endpoint URL');
    console.error('  3. Review firewall rules');
    return;
  }

