    console.error('Issue: All credential sources failed');
    console.error('Attempted credentials:');
    const aggError = error as AggregateAuthenticationError;
    aggError.errors.forEach((err: any, index: number) => {
      console.error(`  ${index + 1}. ${err.name}: ${err.message}`);
    });
    console.error('\nSolutions:');
    console.error('  - Ensure at least one credential source is properly configured');
    console.error('  - Azure: Enable managed identity');
    console.error('  - Local: Run az login or set environment variables');
    return;
  }

  // 6. Resource not found (404)
  if (error.statusCode === 404) {
    console.error('Issue: Resource not found');
    console.error(`  The requested ${serviceName} resource doesn't exist\n`);
    console.error('Solutions:');
    console.error('  1. Verify resource name and URL');
    console.error('  2. Check if resource exists in correct subscription');
    console.error('  3. Confirm you have read permissions');
    return;
  }

  // 7. Generic fallback
  console.error('Issue: Unexpected error');
  console.error(`  Error name: ${error.name || 'Unknown'}`);
  console.error(`  Error code: ${error.code || 'N/A'}`);
  console.error(`  Status code: ${error.statusCode || 'N/A'}`);
  console.error(`  Message: ${error.message}`);
  console.error('\nFull error object:');
  console.error(error);
}

/**
 * Best Practice: Retry with Exponential Backoff
 */
export async function retryWithBackoff<T>(
  operation: () => Promise<T>,
  maxRetries: number = 3,
  initialDelayMs: number = 1000
): Promise<T> {
  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      // Don't retry authorization errors - they won't fix themselves
      if (error.statusCode === 403 || error.statusCode === 401) {
        throw error;
      }

      // Don't retry invalid configuration errors
      if (error.message?.includes('invalid') || error.message?.includes('not found')) {
        throw error;
      }

      if (attempt === maxRetries) {
        throw error;
      }

      // Exponential backoff
      const delayMs = initialDelayMs * Math.pow(2, attempt - 1);
      console.log(`  Retry ${attempt}/${maxRetries} after ${delayMs}ms...`);
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }

  throw lastError;
}

